const helper=`const cols="ABCDEFGHJ";
function parseBoard(r){const s=r.content.filter(x=>x.type==="text").map(x=>x.text).join("\\n");const b={};for(const line of s.split("\\n")){const m=line.match(/^\\s*([1-9])\\s+([.XO](?:\\s+[.XO]){8})\\s+[1-9]\\s*$/);if(m)m[2].split(/\\s+/).forEach((v,i)=>b[cols[i]+m[1]]=v);}return {s,b};}
function neighbors(p){const x=cols.indexOf(p[0]),y=Number(p[1]);return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,z])=>a>=0&&a<9&&z>=1&&z<=9).map(([a,z])=>cols[a]+z);}
function inspect(b){const seen=new Set(),groups=[],regions=[];for(const p of Object.keys(b)){if(seen.has(p))continue;const c=b[p],stack=[p],stones=[],lib=new Set(),border=new Set();seen.add(p);while(stack.length){const q=stack.pop();stones.push(q);for(const n of neighbors(q)){if(b[n]===c&&!seen.has(n)){seen.add(n);stack.push(n);}else if(b[n]!==c){if(b[n]===".")lib.add(n);else border.add(b[n]);}}}if(c===".")regions.push({points:stones.sort(),border:[...border]});else groups.push({color:c,stones:stones.sort(),liberties:[...lib].sort()});}return {groups,regions};}
async function save(){const data=JSON.stringify(load("calls"))+"\\n",old=load("logfile");const patch="*** Begin Patch\\n"+(old?"*** Update File: game-043-log.json\\n@@\\n-"+old.trimEnd()+"\\n+"+data.trimEnd():"*** Add File: game-043-log.json\\n+"+data.trimEnd())+"\\n*** End Patch";text(await tools.apply_patch(patch));store("logfile",data);}
async function play(move,note){const r=await tools.mcp__go__play({move});const {s,b}=parseBoard(r),inv=inspect(b),calls=load("calls");calls.push({kind:"play",move,note,response:r,inspection:inv});store("calls",calls);store("board",b);await save();text(s);text(inv);}
`;
