function neighbors(p){let x=cols.indexOf(p[0]),y=+p[1];return [[x-1,y],[x+1,y],[x,y-1],[x,y+1]].filter(([a,b])=>a>=0&&a<9&&b>=1&&b<=9).map(([a,b])=>cols[a]+b);}
